-- Register risiko diganti dengan isi Formulir Risiko Keberhasilan SMEn (klausul 6.1, 001/SOP-007/KINRA/SMEn/X/2026,
-- berlaku 22 Oktober 2026) bagian Korporasi dan Akuntansi & Keuangan, agar halaman Register sama dengan evidence yang diunggah.
-- 18 risiko lama berasal dari Formulir Isu Internal Eksternal (4.1) dengan penilaian seragam 3 x 2.
-- Baris contoh template ("Operasional dan pemeliharaan gedung/fasilitas kawasan", skor ilustratif) tidak diimpor.
-- Peluang dari formulir 4.1 tetap. Baris formulir 6.1 berjudul "Peluang ..." dicatat sebagai jenis Peluang.
-- Asal Internal/Eksternal tidak ada di formulir 6.1; Eksternal ditetapkan untuk tenant/pihak ketiga, pasokan & tarif, dan kepatuhan hukum.

alter table isu add column if not exists bagian text;
alter table isu add column if not exists proses text;
alter table isu add column if not exists dampak_residual int check (dampak_residual between 1 and 5);
alter table isu add column if not exists kemungkinan_residual int check (kemungkinan_residual between 1 and 5);
alter table isu add column if not exists skor_residual int generated always as (dampak_residual * kemungkinan_residual) stored;
alter table isu add column if not exists signifikan boolean;
alter table isu add column if not exists target text;
alter table isu add column if not exists sumber text;

-- Hapus 18 risiko lama (cocok persis dengan uraian seed 0002); isu lain yang ditambahkan manual tidak disentuh
delete from isu where jenis = 'Risiko' and sumber is null and uraian in (
  'Anggaran operasional untuk program efisiensi energi berkurang.',
  'Anggaran investasi modal untuk penggantian/perbaikan peralatan hemat energi terbatas.',
  'Komitmen atau pemahaman pegawai dan unit kerja terhadap pengelolaan energi belum merata.',
  'Data konsumsi energi per gedung, fasilitas, atau penggunaan signifikan belum lengkap/terintegrasi.',
  'Peralatan tata udara (HVAC), pompa, penerangan, dan utilitas beroperasi di luar kebutuhan aktual.',
  'Pemeliharaan infrastruktur dan peralatan energi tidak konsisten atau tertunda.',
  'Perubahan tingkat hunian, aktivitas tenant, atau kebutuhan layanan kawasan menyebabkan pola konsumsi berubah.',
  'Pembelian atau penggantian peralatan tidak mempertimbangkan kinerja energi.',
  'Kompetensi personel pengoperasian dan pemeliharaan terkait energi belum memadai.',
  'Kebocoran, kerusakan, atau pengaturan tidak tepat pada sistem utilitas meningkatkan konsumsi energi.',
  'Kegiatan administrasi dan operasional gedung menggunakan pencahayaan/peralatan saat tidak diperlukan.',
  'Perubahan proses, renovasi, atau pengembangan fasilitas tidak menilai dampak penggunaan energi sejak tahap perencanaan.',
  'Gangguan pasokan listrik, penurunan kualitas tegangan, atau pemadaman dari jaringan eksternal.',
  'Perubahan tarif energi, biaya beban, atau struktur harga dari penyedia energi.',
  'Cuaca ekstrem, suhu tinggi, curah hujan, atau perubahan iklim meningkatkan kebutuhan pendinginan dan memengaruhi operasi fasilitas.',
  'Perubahan peraturan, persyaratan pemerintah, atau kewajiban pelaporan energi dan lingkungan.',
  'Ketersediaan atau mutu pasokan energi dan layanan dari penyedia eksternal berubah.',
  'Keterbatasan ketersediaan air atau sumber daya pendukung memengaruhi sistem utilitas yang menggunakan energi.'
);

insert into isu (asal, jenis, bagian, proses, uraian, dampak, kemungkinan, dampak_residual, kemungkinan_residual, signifikan, tindakan, evaluasi, pic, target, sumber)
select * from (values
('Internal', 'Risiko', 'Korporasi', 'Tata kelola dan integrasi SMEn korporat', 'Pengelolaan SMEn belum terintegrasi ke perencanaan strategis, KPI, anggaran, keputusan investasi, dan tinjauan kinerja korporat.', 4, 3, 2, 2, true, 'Tetapkan peran, kewenangan, RACI, sasaran, anggaran, agenda tinjauan manajemen dan mekanisme eskalasi; hubungkan dengan rencana korporat.
